    ylabel('$y$', 'FontSize', 14, 'Interpreter', 'latex');
    title('Stream function $\psi$ ($N=36$, $M=16$)', ...
          'FontSize', 14, 'Interpreter', 'latex');
    axis([-0.8 0.8 -0.8 0.8]);
    
    hold on;
    contour(X_phys_valid, Y_phys_valid, UMN_valid, 20, 'k-', 'LineWidth', 0.8);
    
    theta_plot = linspace(ya, yb, 200);
    mtheta_edge = (cos(theta_plot).^4 + sin(theta_plot).^4).^(1./4);
    plot(mtheta_edge.*cos(theta_plot), mtheta_edge.*sin(theta_plot), 'k-', 'LineWidth', 2);
    plot([0, mtheta_edge(1)*cos(ya)], [0, mtheta_edge(1)*sin(ya)], 'k-', 'LineWidth', 2);
    plot([0, mtheta_edge(end)*cos(yb)], [0, mtheta_edge(end)*sin(yb)], 'k-', 'LineWidth', 2);
    hold off;
    grid on;
    set(gca, 'FontSize', 12);
    colormap(jet);
else
    disp('没有找到 UMN_final，请确保 N=36, M=16 时保存了结果');
end